mod test11lib;

use std::env;
use std::io::{self, Write};

use test11lib::atoi::atoi_i32;
use test11lib::inflection::Inflector;

fn write_line<W: Write>(writer: &mut W, bytes: &[u8]) -> io::Result<()> {
    writer.write_all(bytes)?;
    writer.write_all(b"\n")
}

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();
    Inflector::initialize();

    if args.len() > 2 {
        let num = atoi_i32(&args[1]);
        let word = &args[2];
        let mut stdout = io::stdout().lock();

        write_line(&mut stdout, &Inflector::pluralize(word))?;
        write_line(&mut stdout, &Inflector::ordinalize(num))?;
        write_line(&mut stdout, &Inflector::camelize(word, true))?;
        write_line(&mut stdout, &Inflector::camelize(word, false))?;
        write_line(&mut stdout, &Inflector::titleize(word))?;
        write_line(&mut stdout, &Inflector::capitalize(word))?;
        write_line(&mut stdout, &Inflector::truncate(word, 5, "..."))?;
        write_line(&mut stdout, &Inflector::truncate(word, 10, "~"))?;
        write_line(&mut stdout, &Inflector::parameterize(word))?;
        write_line(
            &mut stdout,
            &Inflector::parameterize_with_separator(word, "_"),
        )?;
        write_line(&mut stdout, if Inflector::is_plural(word) { b"1" } else { b"0" })?;
    }

    Ok(())
}

