pub struct Inflector;

impl Inflector {
    pub fn initialize() {}

    pub fn pluralize(word: &str) -> Vec<u8> {
        if word.is_empty() {
            return Vec::new();
        }

        let mut output = Vec::with_capacity(word.len() + 1);
        output.extend_from_slice(word.as_bytes());
        output.push(b's');
        output
    }

    pub fn ordinalize(number: i32) -> Vec<u8> {
        let suffix = match number % 100 {
            11..=13 => "th",
            _ => match number % 10 {
                1 => "st",
                2 => "nd",
                3 => "rd",
                _ => "th",
            },
        };

        format!("{number}{suffix}").into_bytes()
    }

    pub fn camelize(word: &str, lower_camel: bool) -> Vec<u8> {
        let mut output = Vec::with_capacity(word.len());
        let mut uppercase_next = !lower_camel;

        for &byte in word.as_bytes() {
            if byte == b'_' {
                uppercase_next = true;
                continue;
            }

            if uppercase_next {
                output.push(byte.to_ascii_uppercase());
                uppercase_next = false;
            } else {
                output.push(byte);
            }
        }

        output
    }

    pub fn titleize(word: &str) -> Vec<u8> {
        let mut output = Self::ascii_lowercase(word.as_bytes());
        let mut uppercase_next = true;

        for byte in &mut output {
            if uppercase_next {
                *byte = byte.to_ascii_uppercase();
            }
            uppercase_next = *byte == b' ';
        }

        output
    }

    pub fn capitalize(word: &str) -> Vec<u8> {
        let mut output = Self::ascii_lowercase(word.as_bytes());
        if let Some(first) = output.first_mut() {
            *first = first.to_ascii_uppercase();
        }
        output
    }

    pub fn truncate(word: &str, limit: usize, ending: &str) -> Vec<u8> {
        let bytes = word.as_bytes();
        if bytes.len() <= limit {
            return bytes.to_vec();
        }

        let ending_bytes = ending.as_bytes();
        if limit <= ending_bytes.len() {
            return ending_bytes[..limit].to_vec();
        }

        let visible = limit - ending_bytes.len();
        let mut output = Vec::with_capacity(limit);
        output.extend_from_slice(&bytes[..visible]);
        output.extend_from_slice(ending_bytes);
        output
    }

    pub fn parameterize(word: &str) -> Vec<u8> {
        Self::parameterize_with_separator(word, "-")
    }

    pub fn parameterize_with_separator(word: &str, separator: &str) -> Vec<u8> {
        let separator_bytes = separator.as_bytes();
        let mut output = Vec::with_capacity(word.len());

        for &byte in word.as_bytes() {
            if byte.is_ascii_alphanumeric() {
                output.push(byte.to_ascii_lowercase());
            } else if byte == b' ' {
                output.extend_from_slice(separator_bytes);
            }
        }

        Self::trim_separator(output, separator_bytes)
    }

    pub fn is_plural(word: &str) -> bool {
        matches!(word.as_bytes().last(), Some(b's'))
    }

    fn ascii_lowercase(bytes: &[u8]) -> Vec<u8> {
        bytes.iter().map(u8::to_ascii_lowercase).collect()
    }

    fn trim_separator(mut bytes: Vec<u8>, separator: &[u8]) -> Vec<u8> {
        if separator.is_empty() || bytes.is_empty() {
            return bytes;
        }

        let mut start = 0;
        while bytes[start..].starts_with(separator) {
            start += separator.len();
            if start >= bytes.len() {
                return Vec::new();
            }
        }

        let mut end = bytes.len();
        while end >= start + separator.len() && bytes[..end].ends_with(separator) {
            end -= separator.len();
        }

        if start == 0 && end == bytes.len() {
            bytes
        } else {
            bytes.drain(..start);
            bytes.truncate(end - start);
            bytes
        }
    }
