pub fn atoi_i32(input: &str) -> i32 {
    let bytes = input.as_bytes();
    let mut index = 0;

    while index < bytes.len() && bytes[index].is_ascii_whitespace() {
        index += 1;
    }

    let mut negative = false;
    if index < bytes.len() {
        match bytes[index] {
            b'+' => index += 1,
            b'-' => {
                negative = true;
                index += 1;
            }
            _ => {}
        }
    }

    let digits_start = index;
    let mut magnitude = 0_u128;
    while index < bytes.len() && bytes[index].is_ascii_digit() {
        let digit = u128::from(bytes[index] - b'0');
        magnitude = magnitude.saturating_mul(10).saturating_add(digit);
        index += 1;
    }

    if index == digits_start {
        return 0;
    }

    let signed = if negative {
        let negative_limit = (i64::MAX as u128) + 1;
        if magnitude >= negative_limit {
            i64::MIN
        } else {
            -(magnitude as i64)
        }
    } else if magnitude >= i64::MAX as u128 {
        i64::MAX
    } else {
        magnitude as i64
    };

    signed as i32
}

#[cfg(test)]
mod tests {
    use super::atoi_i32;

    #[test]
    fn parses_prefixes_like_atoi() {
        assert_eq!(atoi_i32("12abc"), 12);
        assert_eq!(atoi_i32("  +12"), 12);
        assert_eq!(atoi_i32("--1"), 0);
        assert_eq!(atoi_i32(""), 0);
    }

    #[test]
    fn wraps_after_i64_saturation() {
        assert_eq!(atoi_i32("2147483648"), -2147483648);
        assert_eq!(atoi_i32("4294967295"), -1);
        assert_eq!(atoi_i32("-2147483649"), 2147483647);
        assert_eq!(atoi_i32("-9999999999999999999999999"), 0);
    }
}

